-- Brief sharing and referral (#507). brief_share holds a sanitised brief snapshot behind a sha-256 token hash under FORCE RLS on app.workspace_id; app_brief_share_view() is the one cross-workspace read (a signed-out recipient has no workspace), by token hash only, returning the snapshot, its creator and its state and no other column. referral and referral_credit are global (GLOBAL_TABLES, no RLS): user ids, a share id and month counts only; the app role may read, insert and update them, never delete; the clerk role gets nothing. New tables and one function only: nothing existing is altered or dropped.
CREATE TABLE "brief_share" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"token_hash" text NOT NULL,
	"snapshot" jsonb NOT NULL,
	"created_by" uuid,
	"expires_at" timestamp with time zone NOT NULL,
	"revoked_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "brief_share_token_hash_uq" UNIQUE("token_hash"),
	CONSTRAINT "brief_share_snapshot_chk" CHECK (jsonb_typeof("brief_share"."snapshot") = 'object')
);
--> statement-breakpoint
